CREATE TABLE issues_definition_history (workspace_id TEXT NOT NULL,definition_kind TEXT NOT NULL CHECK(definition_kind IN ('status','type')),definition_id TEXT NOT NULL,version INTEGER NOT NULL,action TEXT NOT NULL,actor_id TEXT NOT NULL,actor_kind TEXT NOT NULL CHECK(actor_kind IN ('human','machine')),occurred_at INTEGER NOT NULL,detail TEXT NOT NULL,PRIMARY KEY(workspace_id,definition_kind,definition_id,version));
CREATE TABLE issues_definition_receipts (workspace_id TEXT NOT NULL,principal_id TEXT NOT NULL,operation_id TEXT NOT NULL,fingerprint TEXT NOT NULL,definition_kind TEXT NOT NULL CHECK(definition_kind IN ('status','type')),result_id TEXT NOT NULL,result_version INTEGER NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(workspace_id,principal_id,operation_id));
CREATE TABLE issues_task_statuses (workspace_id TEXT NOT NULL,id TEXT NOT NULL,key TEXT NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('todo','in_progress','done','cancelled')),color TEXT,position INTEGER NOT NULL DEFAULT 0,is_default INTEGER NOT NULL DEFAULT 0 CHECK(is_default IN (0,1)),is_review_step INTEGER NOT NULL DEFAULT 0 CHECK(is_review_step IN (0,1)),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,key));
CREATE TABLE issues_task_types (workspace_id TEXT NOT NULL,id TEXT NOT NULL,key TEXT NOT NULL,name TEXT NOT NULL,color TEXT,icon TEXT,position INTEGER NOT NULL DEFAULT 0,is_default INTEGER NOT NULL DEFAULT 0 CHECK(is_default IN (0,1)),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,key));
CREATE TABLE issues_links (workspace_id TEXT NOT NULL,id TEXT NOT NULL,source_issue_id TEXT NOT NULL,target_issue_id TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('blocks','relates_to','duplicates','follows_from')),created_by_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,source_issue_id,target_issue_id,type),FOREIGN KEY(workspace_id,source_issue_id) REFERENCES issues_issues(workspace_id,id),FOREIGN KEY(workspace_id,target_issue_id) REFERENCES issues_issues(workspace_id,id));
CREATE TRIGGER issues_freeze_task_statuses_insert BEFORE INSERT ON issues_task_statuses WHEN (EXISTS(SELECT 1 FROM issues_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id='')) AND NOT EXISTS(SELECT 1 FROM issues_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=''))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER issues_freeze_task_statuses_update BEFORE UPDATE ON issues_task_statuses WHEN (EXISTS(SELECT 1 FROM issues_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id='')) AND NOT EXISTS(SELECT 1 FROM issues_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=''))) OR (EXISTS(SELECT 1 FROM issues_frozen_scopes f WHERE f.workspace_id=OLD.workspace_id AND (f.project_id='' OR f.project_id='')) AND NOT EXISTS(SELECT 1 FROM issues_purge_bypass b WHERE b.workspace_id=OLD.workspace_id AND (b.project_id='' OR b.project_id=''))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER issues_freeze_task_statuses_delete BEFORE DELETE ON issues_task_statuses WHEN (EXISTS(SELECT 1 FROM issues_frozen_scopes f WHERE f.workspace_id=OLD.workspace_id AND (f.project_id='' OR f.project_id='')) AND NOT EXISTS(SELECT 1 FROM issues_purge_bypass b WHERE b.workspace_id=OLD.workspace_id AND (b.project_id='' OR b.project_id=''))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
